"""Fixed solver process entry; receives input and a per-question gateway token."""

import importlib.util
import json
import re
import sys

from langchain_core.callbacks import BaseCallbackHandler
from langchain_openai import ChatOpenAI
from openai import OpenAI

EXPLICIT_CACHE = False


def mark_cache_prefix(messages):
    """Cache the stable prefix and history through the latest message."""
    prefix = [
        index for index, message in enumerate(messages)
        if message.get("role") in {"system", "user"}
    ][:2]
    marked = {*prefix, len(messages) - 1}
    out = []
    for index, message in enumerate(messages):
        if index in marked:
            content = message.get("content")
            if isinstance(content, str):
                message = dict(message, content=[{
                    "type": "text", "text": content,
                    "cache_control": {"type": "ephemeral"},
                }])
            elif isinstance(content, list) and content:
                blocks = [dict(block) if isinstance(block, dict) else block for block in content]
                if isinstance(blocks[-1], dict):
                    blocks[-1]["cache_control"] = {"type": "ephemeral"}
                message = dict(message, content=blocks)
        out.append(message)
    return out


class DeepSeekChatOpenAI(ChatOpenAI):
    """Preserve DeepSeek reasoning across the harness's non-streaming tool turns."""

    def _create_chat_result(self, response, generation_info=None):
        result = super()._create_chat_result(response, generation_info)
        data = response if isinstance(response, dict) else response.model_dump()
        for generation, choice in zip(result.generations, data["choices"]):
            if "reasoning_content" in choice["message"]:
                generation.message.additional_kwargs["reasoning_content"] = choice["message"]["reasoning_content"]
        return result

    def _get_request_payload(self, input_, *, stop=None, **kwargs):
        payload = super()._get_request_payload(input_, stop=stop, **kwargs)
        if "max_completion_tokens" in payload:
            payload["max_tokens"] = payload.pop("max_completion_tokens")
        for message, original in zip(payload["messages"], self._convert_input(input_).to_messages()):
            if original.type == "ai" and "reasoning_content" in original.additional_kwargs:
                message["reasoning_content"] = original.additional_kwargs["reasoning_content"]
        if EXPLICIT_CACHE:
            payload["messages"] = mark_cache_prefix(payload["messages"])
        return payload


def has_final_answer_field(text):
    """True if the response is (or contains) JSON carrying a final_answer field."""
    if not text:
        return False
    try:
        data = json.loads(text)
        if isinstance(data, dict) and "final_answer" in data:
            return True
    except (json.JSONDecodeError, TypeError):
        pass
    return bool(re.search(r'"final_answer"\s*:', text))


def reformat_to_schema(client, model, response):
    """One no-think json_object call to wrap a free-form answer into the schema."""
    result = client.chat.completions.create(
        model=model,
        messages=[
            {"role": "system", "content": "You convert answers into JSON. Output only JSON."},
            {"role": "user", "content": (
                'Convert the following answer into a JSON object with exactly two string'
                ' fields, "reasoning" and "final_answer". Copy the answer content unchanged,'
                ' preserving any required markup such as [DIAGNOSIS]...[/DIAGNOSIS] inside'
                f' final_answer.\n\nAnswer:\n\n{response}'
            )},
        ],
        response_format={"type": "json_object"},
        extra_body={"enable_thinking": False},
    )
    converted = result.choices[0].message.content or ""
    return converted if has_final_answer_field(converted) else response


class ToolTrace(BaseCallbackHandler):
    def on_tool_start(self, serialized, input_str, *, run_id, **kwargs):
        self.emit("tool_start", run_id=str(run_id), name=serialized.get("name"), input=input_str)

    def on_tool_end(self, output, *, run_id, **kwargs):
        value = output.model_dump(mode="json") if hasattr(output, "model_dump") else str(output)
        self.emit("tool_end", run_id=str(run_id), output=value)

    def on_tool_error(self, error, *, run_id, **kwargs):
        self.emit("tool_error", run_id=str(run_id), error=str(error))

    @staticmethod
    def emit(event, **values):
        print(json.dumps({"event": event, **values}, ensure_ascii=False), flush=True)


def main():
    request = json.load(sys.stdin)
    config = request["solver"]
    global EXPLICIT_CACHE
    EXPLICIT_CACHE = bool(config.get("explicit_cache"))
    # The subclass is provider-agnostic: it preserves reasoning_content across tool
    # turns and keeps the wire field as max_tokens, which DashScope (qwen) requires.
    model_class = DeepSeekChatOpenAI if config.get("provider") in {"deepseek", "qwen"} else ChatOpenAI
    model = model_class(
        model=config["model"],
        base_url=request["gateway_url"],
        api_key=request["gateway_token"],
        temperature=config["temperature"],
        max_tokens=config["max_tokens"],
        reasoning_effort=config.get("reasoning_effort"),
        extra_body=config.get("extra_body"),
        timeout=config.get("client_timeout_seconds", config["request_timeout_seconds"]),
        max_retries=0,
        streaming=False,
        use_responses_api=False,
        profile={
            "tool_calling": True,
            "max_input_tokens": config["context_window"],
            "max_output_tokens": config["max_tokens"],
        },
    )
    sys.path.insert(0, "/harness")
    spec = importlib.util.spec_from_file_location("candidate", "/harness/agent.py")
    candidate = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(candidate)
    agent, prompt = candidate.build_agent(model, request["input"], config)
    if config.get("answer_guard"):
        prompt += (
            "\n\nFINAL OUTPUT REQUIREMENT (mandatory, overrides anything else): Your final"
            ' message MUST be a single JSON object with exactly two string fields,'
            ' "reasoning" and "final_answer". Put the answer itself (keeping any required'
            ' markup such as [DIAGNOSIS]...[/DIAGNOSIS]) inside "final_answer". Output'
            " nothing outside the JSON object."
        )
    result = agent.invoke(
        {"messages": [{"role": "user", "content": prompt}]},
        config={"callbacks": [ToolTrace()], "recursion_limit": config["max_model_calls"] * 4 + 20},
    )
    response = result["messages"][-1].content
    if isinstance(response, list):
        response = "".join(block if isinstance(block, str) else block.get("text", "") for block in response)
    if config.get("answer_guard") and not has_final_answer_field(response):
        guard_client = OpenAI(
            base_url=request["gateway_url"], api_key=request["gateway_token"],
            timeout=config["client_timeout_seconds"], max_retries=0,
        )
        response = reformat_to_schema(guard_client, config["model"], response)
    ToolTrace.emit("final", response=response)


if __name__ == "__main__":
    main()

"""Per-run model gateway: global concurrency, per-question budgets, full traces."""

from dataclasses import dataclass, field
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
import threading
import time
import uuid

import httpx

from .errors import classify_error


def merge_chunk(response, chunk):
    """Assemble an upstream stream into the solver's usual complete response."""
    for key in ("id", "created", "model", "system_fingerprint", "usage", "error"):
        if chunk.get(key) is not None:
            response[key] = chunk[key]
    response["object"] = "chat.completion"
    choices = response.setdefault("choices", [])
    for part in chunk.get("choices", []):
        index = part["index"]
        while len(choices) <= index:
            choices.append({
                "index": len(choices), "message": {"role": "assistant", "content": ""},
                "finish_reason": None,
            })
        choice = choices[index]
        if part.get("finish_reason") is not None:
            choice["finish_reason"] = part["finish_reason"]
        message = choice["message"]
        delta = part.get("delta") or {}
        for key in ("content", "reasoning_content", "refusal"):
            if delta.get(key) is not None:
                message[key] = message.get(key, "") + delta[key]
        for tool in delta.get("tool_calls") or []:
            calls = message.setdefault("tool_calls", [])
            while len(calls) <= tool["index"]:
                calls.append({"id": "", "type": "function", "function": {"name": "", "arguments": ""}})
            call = calls[tool["index"]]
            if tool.get("id"):
                call["id"] = tool["id"]
            for key, value in (tool.get("function") or {}).items():
                if value is not None:
                    call["function"][key] += value


@dataclass
class Job:
    deadline: float
    max_calls: int
    calls: int = 0
    input_tokens: int = 0
    output_tokens: int = 0
    closed: bool = False
    error: dict | None = None
    rows: list = field(default_factory=list)
    lock: threading.Lock = field(default_factory=threading.Lock)

    def reserve(self):
        with self.lock:
            if self.closed or time.monotonic() >= self.deadline:
                self.error = classify_error("Question deadline exceeded")
                raise RuntimeError("Question deadline exceeded")
            if self.max_calls > 0 and self.calls >= self.max_calls:
                self.error = classify_error("Question model-call limit exceeded")
                raise RuntimeError("Question model-call limit exceeded")
            self.calls += 1
            return self.calls

    def record(self, row):
        """Keep the call in memory; the conversation file is written once, at the end."""
        with self.lock:
            usage = row.get("response", {}).get("usage") or {}
            self.input_tokens += usage.get("prompt_tokens", 0) or 0
            self.output_tokens += usage.get("completion_tokens", 0) or 0
            self.error = row.get("error")
            self.rows.append(row)

    def finish(self):
        with self.lock:
            self.closed = True
            return {
                "model_calls": self.calls,
                "input_tokens": self.input_tokens,
                "output_tokens": self.output_tokens,
            }


class Gateway:
    def __init__(self, solver: dict, concurrency: int):
        self.solver = solver
        self.slots = threading.BoundedSemaphore(concurrency)
        self.jobs = {}
        self.client = httpx.Client(trust_env=False)
        self.max_retries = solver.get("max_retries", 0)
        self.retry_backoff = solver.get("retry_backoff_seconds", 5)
        self.api_key = os.environ.get(solver["api_key_env"], "local")
        gateway = self

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def send(self, status, content):
                body = json.dumps(content, ensure_ascii=False).encode()
                try:
                    self.send_response(status)
                    self.send_header("Content-Type", "application/json")
                    self.send_header("Content-Length", str(len(body)))
                    self.end_headers()
                    self.wfile.write(body)
                except (BrokenPipeError, ConnectionResetError):
                    pass

            def do_POST(self):
                if self.path != "/v1/chat/completions":
                    self.send(404, {"error": {"message": "Unknown endpoint"}})
                    return
                token = self.headers.get("Authorization", "").removeprefix("Bearer ")
                job = gateway.jobs.get(token)
                if job is None:
                    self.send(401, {"error": {"message": "Unknown question token"}})
                    return
                try:
                    payload = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
                    call_id = job.reserve()
                except (ValueError, KeyError, RuntimeError) as error:
                    self.send(400, {"error": {"message": str(error)}})
                    return
                payload["model"] = gateway.solver["model"]
                payload["stream"] = True
                payload["stream_options"] = {**payload.get("stream_options", {}), "include_usage": True}
                payload["max_tokens"] = min(
                    payload.get("max_tokens", gateway.solver["max_tokens"]),
                    gateway.solver["max_tokens"],
                )
                started = time.monotonic()
                status = 502
                response = {}
                acquired = gateway.slots.acquire(timeout=max(0, job.deadline - started))
                try:
                    if not acquired or time.monotonic() >= job.deadline:
                        raise TimeoutError("Question deadline exceeded while queued")
                    attempts = gateway.max_retries + 1
                    for attempt in range(attempts):
                        if attempt:
                            call_id = job.reserve()
                        attempt_started = time.monotonic()
                        response = {}
                        chunks = []
                        first_chunk_seconds = None
                        try:
                            with gateway.client.stream(
                                "POST",
                                gateway.solver["api_base"].rstrip("/") + "/chat/completions",
                                headers={"Authorization": f"Bearer {gateway.api_key}"},
                                json=payload,
                                timeout=min(
                                    gateway.solver["request_timeout_seconds"],
                                    job.deadline - time.monotonic(),
                                ),
                            ) as upstream:
                                status = upstream.status_code
                                if status >= 400:
                                    upstream.read()
                                    try:
                                        response = upstream.json()
                                    except ValueError:
                                        response = {"error": {"message": "Upstream returned non-JSON content"}}
                                else:
                                    complete = False
                                    for line in upstream.iter_lines():
                                        if job.closed or time.monotonic() >= job.deadline:
                                            raise TimeoutError("Question deadline exceeded")
                                        if not line.startswith("data:"):
                                            continue
                                        data = line[5:].strip()
                                        if data == "[DONE]":
                                            complete = True
                                            break
                                        chunk = json.loads(data)
                                        if first_chunk_seconds is None:
                                            first_chunk_seconds = time.monotonic() - attempt_started
                                        chunks.append(line)
                                        merge_chunk(response, chunk)
                                    if not complete and not response.get("error"):
                                        raise httpx.RemoteProtocolError("Upstream stream ended before [DONE]")
                            retryable = status in {408, 429} or status >= 500 or (
                                response.get("error") and response["error"].get("type")
                                in {"ReadTimeout", "ConnectError", "ConnectTimeout", "ReadError"}
                            )
                        except (httpx.HTTPError, TimeoutError, ValueError) as error:
                            status = 502
                            response = {"error": {"message": str(error), "type": type(error).__name__}}
                            retryable = True
                        finally:
                            failure = classify_error(
                                response.get("error", {"message": f"HTTP {status}"}),
                                status, gateway.solver.get("error_patterns"),
                            ) if status >= 400 or response.get("error") else None
                            job.record({
                                "call_index": call_id, "attempt": attempt + 1,
                                "time": datetime.now(timezone.utc).isoformat(),
                                "elapsed_seconds": time.monotonic() - attempt_started,
                                "first_chunk_seconds": first_chunk_seconds,
                                "stream_chunks": len(chunks),
                                "status_code": status, "request": payload,
                                "response": response, "error": failure,
                            })
                        if not retryable or attempt == attempts - 1:
                            break
                        time.sleep(min(gateway.retry_backoff * (2 ** attempt), 60))
                except Exception as error:
                    response = {"error": {"message": str(error), "type": type(error).__name__}}
                    job.error = classify_error(error, patterns=gateway.solver.get("error_patterns"))
                finally:
                    if acquired:
                        gateway.slots.release()
                self.send(status, response)

        self.server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        self.server.daemon_threads = True
        self.url = f"http://127.0.0.1:{self.server.server_port}/v1"

    def __enter__(self):
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()
        return self

    def __exit__(self, *args):
        self.server.shutdown()
        self.server.server_close()
        self.thread.join()
        self.client.close()

    def register(self, timeout_seconds=None, max_calls=None):
        token = uuid.uuid4().hex
        job = Job(
            deadline=time.monotonic() + (timeout_seconds or self.solver["timeout_seconds"]),
            max_calls=self.solver["max_model_calls"] if max_calls is None else max_calls,
        )
        self.jobs[token] = job
        return token, job

