from benchmark.data.evaluators import eval_uspto, eval_symptom2disease, eval_lawbench

RUNS = {
 'fb204702a72dc3e2168539118386bdb4a460371c':'d4199a2',
 '13b8664bc78f4264c10a36e67028dfdb45cecde2':'3a72aec',
 '0d30915e47bd94e37ce6b62f68b611bff0458b14':'32b0dc3',
