 '9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7':'baseline',
}
def attempts(rec):
    out=[]
    for l in [rec['messages']]+rec.get('side_calls',[]):
        last=l[-1] if l else None
        if isinstance(last,dict) and last.get('role')=='assistant' and not last.get('tool_calls'):
            c=last.get('content')
            if isinstance(c,str) and c.strip(): out.append(c)
    return out

def score_answer(task, answer, target):
    if task=='USPTO': return bool(eval_uspto(answer,target)['correct'])
    if task=='Symptom2Disease': return bool(eval_symptom2disease(answer,target))
    return bool(eval_lawbench(answer,target)['was_correct'])

def load_task(task):
    """pools[(example,)] = list of (run, raw_reply, grounded_reply, target)"""
    pools=collections.defaultdict(list); targets={}
    for tree,label in RUNS.items():
        root=f'/workspace/runs/{tree}'
        d=os.path.join(root,task,'conversations')
        if not os.path.isdir(d): continue
        space=A.load_answer_space(os.path.join(root,task,'memory.json'))
        for ex in sorted(os.listdir(d)):
            if not ex.isdigit(): continue
            for f in sorted(os.listdir(os.path.join(d,ex))):
                if not f.endswith('.json'): continue
                rec=json.load(open(os.path.join(d,ex,f)))
                targets[int(ex)]=rec['target']
                for a in attempts(rec):
                    pools[int(ex)].append((label,a,A.ground_reply(a,space)))
    return pools,targets

def evaluate(task,pools,targets):
    """Returns dict label->accuracy for graded answers."""
    res=collections.defaultdict(list)
    for ex,items in pools.items():
        t=targets[ex]
        for label,raw,g in items:
            ans=extract_json_field(g,'final_answer')
            res['raw:'+label].append(score_answer(task,ans if task!='Symptom2Disease' else ans,t))
            res['grounded:'+label].append(score_answer(task,extract_json_field(g,'final_answer'),t))
    return {k:sum(v)/len(v) for k,v in res.items()}
