import json, collections, random, sys, os
sys.path.insert(0,'/workspace/harness/solver'); sys.path.insert(0,'/workspace')
import pool as P
import answer_space as A
from benchmark.answers import extract_json_field
from benchmark.data.evaluators import eval_uspto, eval_symptom2disease, eval_lawbench

def correct(task, answer, target):
    if task=='USPTO': return bool(eval_uspto(answer,target)['correct'])
    if task=='Symptom2Disease': return bool(eval_symptom2disease(answer,target))
    return bool(eval_lawbench(answer,target)['correct'])

def ans_of(reply):
    return extract_json_field(reply,'final_answer')

def vote(task, replies, targets, k, trials=400, seed=0):
    rng=random.Random(seed)
    hits=0; n=0
    for ex,items in replies.items():
        if len(items)<k: continue
        t=targets[ex]
        for _ in range(trials):
            sample=rng.sample(items,k)
            grounded=[g for _,_,g in sample]
            w=grounded[A.panel_winner(grounded)]
            hits+=correct(task,ans_of(w),t); n+=1
    return hits/n if n else 0.0

def oracle(task, replies, targets):
    hits=0
    for ex,items in replies.items():
        t=targets[ex]
        hits+= any(correct(task,ans_of(g),t) for _,_,g in items)
    return hits/len(replies)

if __name__=='__main__':
    for task in ['USPTO','Symptom2Disease','LawBench']:
        pools,targets=P.load_task(task)
        n_rep=sum(len(v) for v in pools.values())
        print(f'=== {task}: examples={len(pools)} replies={n_rep} per-example={n_rep/len(pools):.1f}')
        print('   oracle over all pooled replies: %.3f' % oracle(task,pools,targets))
        for k in [1,2,3,5,8,10]:
            print('   vote k=%d: %.3f' % (k, vote(task,pools,targets,k)))
